def discount(price: float, percent: float) -> float:
    return price * (1 - percent / 100)

total: float = discount(1000, 15)
print(total)   # 850.0

def full_name(first: str, last: str, middle: str = "") -> str:
    if middle:
        return f"{first} {middle} {last}"
    return f"{first} {last}"

from typing import Optional

def find_user(names: list[str], target: str) -> Optional[str]:
    for name in names:
        if name == target:
            return name
    return None

found = find_user(["Аня", "Марк"], "Оля")
if found is None:          # mypy потребует такую проверку
    print("пользователь не найден")

